;
;		Name:		00runtime.asm
;		Purpose:	Runtime interpreter main
;		Created:	11th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										Execute runtime. 
;
;		AA00		is the runtime p-code.
;		XX00 		is the start of memory for strings / stack / etc.
;		YY00 		is the end of memory.
;
;		So if A = $32 and X = $70 and Y = $78 the code is at $3200 and the useable memory
;		is from $7000-$77FF.
;
;		Carry set on exit if error.
;
; ************************************************************************************************

StartRuntime:			
		sta 	runtimeHigh 				; save address of code.		
		sta 	codePtr+1 					; set pointer to code.
		stz 	codePtr

		stx 	storeStartHigh 				; save from-to address.
		sty 	storeEndHigh
		stx 	variableStartPage
		;
		;		The frame stack grows DOWN from storeStartHigh-1:$FF (clr.asm) into the gap the
		;		compiler leaves below the workspace for it -- FrameStackPages, spent by object.asm
		;		in both embedded and shared modes. Nothing policed the bottom of that gap, so a
		;		runaway recursion carried straight on into the object code, overwrote the program
		;		and then executed what it had written. Work the floor out once, here.
		;
		;		Here and not in ClearMemory: a LOAD chain skips ClearMemory (see below) to keep the
		;		previous program's variables, but it still arrives through this entry point, and it
		;		still has a stack that can overflow.
		;
		txa
		sec
		sbc 	#FrameStackPages
		sta 	stackFloorHigh
		;
		;		Same argument for the stack pointer itself, and for the same reason it is here and
		;		not in ClearMemory: a chained program must start with an EMPTY stack of its OWN.
		;		The chain carries variables, never frames -- it re-enters through the ROM's RUN, so
		;		the loader's frames are gone whatever this says. See ResetRuntimeStack in clr.asm.
		;
		jsr 	ResetRuntimeStack

		tsx 								; save the stack.
		stx 	Runtime6502SP 

		ldy 	#RuntimeErrorHandler >> 8 	; set error handler to runtime one.
		ldx 	#RuntimeErrorHandler & $FF
		jsr 	SetErrorHandler

		;
		;		Fresh start clears the variable space; a LOAD chain does NOT, so the loaded
		;		program inherits this one's variables and strings. LOAD (load.asm) arms a
		;		signature in low RAM before it chains -- it survives the load (it is below the
		;		program) and RUN's CLR. If it is set, disarm it and keep the variables.
		;
		ldx 	#3
_SRChainCheck:
		lda 	loadChainSig,x
		cmp 	LoadChainMagic,x
		bne 	_SRFreshStart
		dex
		bpl 	_SRChainCheck
		lda 	#0 							; matched: disarm the signature and preserve memory
		ldx 	#3
_SRDisarm:
		sta 	loadChainSig,x
		dex
		bpl 	_SRDisarm
		bra 	_SRAfterClear
_SRFreshStart:
		jsr 	ClearMemory 				; clear memory.
_SRAfterClear:
		jsr 	XRuntimeSetup 				; initialise the runtime stuff.
	 	jsr		SetDefaultChannel			; set default input/output channel.

		jsr 	RestoreCode 				; which we now call
		;
		;		Main Run Loop
		;
		bra 	NXStartLoop 				; step over the out-of-line break check below
		;
		;		The Ctrl+C poll, lifted out of the dispatch path. It runs once every 16 p-code
		;		words; the counter test in front of it runs on EVERY word, which makes it the
		;		hottest four instructions in the runtime. It used to be
		;
		;			lda breakCount / adc #16 / sta breakCount / bcc		= 13 cycles
		;
		;		and is now dec/beq = 8, for the same one-in-16 rate. Five cycles a p-code word,
		;		on every keyword of every program. breakCount needs no initialising: whatever it
		;		holds at entry, the first poll lands within 256 words and every one after that is
		;		on the 16 re-armed here.
		;
		;		These three are deliberately GLOBAL labels, not the _-prefixed locals used
		;		elsewhere in this file: 64tass scopes a _ label to the enclosing global one, so
		;		a check sitting above NextCommand cannot branch to a local defined below it.
		;
NXBreakCheck:
		phx
		phy 								; check Ctrl+C
		jsr 	XCheckStop
		ply
		plx
		lda 	#16 						; re-arm the counter for the next 16 words
		sta 	breakCount
		bra 	NXDispatch
NXStartLoop:
		ldy 	#0
NextCommand:
		dec 	breakCount 					; only check every 16 instructions.
		beq 	NXBreakCheck
NXDispatch:
		lda 	(codePtr),y 				; get next
		bmi 	NXCommand 					; -if -ve command
		iny
		cmp 	#64 						; 64..127 is load and store.
		bcc 	PushByteA 					; 0..63 is short constants.
		;
		;		Load/Store dispatch.
		;
NXLoadStore:
		cmp		#120 						; is it an indirect read/write
		bcs 	NXIndirectLoadStore
		lsr 	a 							; / 4, so $48 => $12,
		lsr 	a 
		and 	#$0E
		phx 								; get ready to jump
		tax
		jmp 	(ReadWriteVectors,x) 		; go via the jump table.

ReadWriteVectors:
		.word 	ReadFloatCommand			; read float
		.word 	WriteFloatCommand 			; write float
		.word 	ReadIntegerCommand 			; read integer
		.word 	WriteIntegerCommand 		; write integer
		.word 	ReadStringCommand 			; read string
		.word 	WriteStringCommand 			; write string
		.word 	Unimplemented 				
		.word 	Unimplemented 		
		;
		;		Indirect Load/store dispatch
		;
NXIndirectLoadStore:
		and 	#7
		asl 	a
		phx
		tax
		jmp 	(IndirectVectors,x)

IndirectVectors:
		.word 	IndFloatRead 				; float read				
		.word 	IndInt16Read 				; int16 read				
		.word 	IndStringRead 				; string read				
		.word 	Unimplemented
		.word 	IndFloatWrite				; float write
		.word 	IndInt16Write 				; int16 write				
		.word 	IndStringWrite 				; string write				
		.word 	Unimplemented

		;		
		;		Push byte on stack
		;
PushByteCommand: ;; [.byte]			
		.entercmd
		lda 	(codePtr),y 				; get byte to write.
		iny
PushByteA:		
		inx 								; push constant on stack
		sta 	NSMantissa0,x 				; save byte
		stz 	NSMantissa1,x 				; clear MSB
ClearRestWord:		
		stz 	NSMantissa2,x 				; zero upper bytes, exponent, make iFloat32
		stz 	NSMantissa3,x
		stz 	NSExponent,x
		stz 	NSStatus,x
		bra 	NextCommand
		;
		;		Push a word on the stack
		;
PushWordCommand: ;; [.word]
		.entercmd
		inx
		lda 	(codePtr),y 				; word to stack
		iny
		sta 	NSMantissa0,x		
		lda 	(codePtr),y
		iny
		sta 	NSMantissa1,x		
		bra 	ClearRestWord 				; handle everything else.
		;
		;		Execute a command
		;
NXCommand:
		iny 								; consume command.
		bpl 	_NXCommandNoFixUp
		jsr 	FixUpY
_NXCommandNoFixUp:		
		asl 	a 							; shift left 
		phx 								; save SP on stack
		tax				 					; and jump indirect
		jmp 	(VectorTable,x)

; ************************************************************************************************
;
;		Called after Y is negative after incrementing in the two main fetches, it resets
;		Y to zero and adds it to the codePtr ; thus we don't do lots of 16 bit increments,
;		nor are we limited to 1/4 k of P-Code per line.
;
; ************************************************************************************************

FixUpY:	
		pha
		tya
		clc 
		adc 	codePtr
		sta 	codePtr
		bcc 	_NoCPCarry
		inc 	codePtr+1
_NoCPCarry:
		ldy 	#0
		pla
		rts

; ************************************************************************************************
;
;		The signature LOAD writes to loadChainSig to say "this is a chain -- keep the variables".
;		Four bytes so a cold-boot random match is a non-event; shared with load.asm so both ends
;		agree on it.
;
; ************************************************************************************************

LoadChainMagic:
		.text 	"GPCL"

		.send code

		.section storage
runtimeHigh:								; high byte of runtime start.
		.fill 	1

loadChainSig: 								; LOAD arms this before chaining; StartRuntime disarms it
		.fill 	4 							; and skips the memory clear so variables survive the chain

storeStartHigh:								; p-code run space.
		.fill 	1
storeEndHigh:
		.fill 	1

stackFloorHigh: 							; lowest page the FOR/GOSUB frame stack may occupy;
		.fill 	1 							; storeStartHigh - FrameStackPages, tested by
											; StackOpenFrame (stack/frames.asm)

variableStartPage: 							; variable start high
		.fill 	1		

Runtime6502SP: 								; 6502 stack on start.
		.fill 	1		
		
breakCount: 								; counter so don't check break every instruction.
		.fill 	1		
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		02/08/26		Reset runtimeStackPtr on both paths, chain included; ClearMemory is skipped
;						on a chain and took the stack reset with it.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		abs.asm
;		Purpose:	Absolute value of TOS
