; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		andor.asm
;		Purpose:	And/Or operators
;		Created:	14th April 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;									AND/OR code
;
; ************************************************************************************************

BinaryAnd: ;; [and]
		.entercmd
		sec
		bra 	AndOrCommon
BinaryOr: ;; [or]
		.entercmd
		clc

AndOrCommon:
		php 								; save AND/OR flag
			 								; convert both to 16 bit format.
		jsr 	AndOrGet16
		dex
		jsr 	AndOrGet16

		plp
		bcc 	_AOCOrCode
	
		lda 	NSMantissa0,x 				; AND code
		and		NSMantissa0+1,x
		sta 	NSMantissa0,x
		lda 	NSMantissa1,x
		and		NSMantissa1+1,x
		sta 	NSMantissa1,x
		bra 	_AOCComplete
_AOCOrCode:
		lda 	NSMantissa0,x 				; OR code
		ora		NSMantissa0+1,x
		sta 	NSMantissa0,x
		lda 	NSMantissa1,x
		ora		NSMantissa1+1,x
		sta 	NSMantissa1,x
_AOCComplete:		
		stz 	NSStatus,x 					; make integer ?
		bit 	NSMantissa1,x 				; result is -ve
		bpl 	_AOCExit

		jsr 	Negate16Bit 				; 2's complement
		lda 	#$80 						; make it -ve
		sta 	NSStatus,x
_AOCExit:
		.exitcmd

; ************************************************************************************************
;
;		Truncate one operand to an integer and convert it to 16 bit two's complement, rejecting
;		anything that will not fit. AND/OR are 16 bit operations here, as they are in stock X16
;		BASIC, but the old code reached GetInteger16Bit directly and that only ever touches
;		Mantissa0/1 -- Mantissa2/3 were left holding the top half of the operand and rode
;		straight through into the result:
;
;			70000 AND -1  ->  70000        ($00011170, low word ANDed, $0001 untouched)
;			4294967295 AND 0  ->  4294901760   ($FFFF0000)
;
;		Stock raises ?ILLEGAL QUANTITY ERROR for an operand outside -32768..32767 rather than
;		returning something, so range check instead of masking: measured against R49, 32767 and
;		-32768 are accepted, 32768, 65535, 65536, -32769 and 70000 are all rejected, and a
;		fraction truncates (3.7 AND -1 = 3) in both. Checking has to happen on the MAGNITUDE,
;		before the two's complement conversion -- afterwards -32768 and -40000 both leave a
;		high byte with bit 7 set and are indistinguishable.
;
; ************************************************************************************************

AndOrGet16:
		.floatinteger 						; truncate toward zero first: the range is checked
											; against the integer part, as stock's is.
		lda 	NSMantissa2,x 				; magnitude must fit in 16 bits at all.
		ora 	NSMantissa3,x
		bne 	_AOGRange
		lda 	NSMantissa1,x
		bpl 	_AOGConvert 				; magnitude <= $7FFF is always fine.
		;
		;		$8000..$FFFF is legal only as exactly -32768.
		;
		bit 	NSStatus,x 					; BIT leaves A alone, so Mantissa1 survives the test
		bpl 	_AOGRange 					; positive -> 32768 or above -> out of range
		cmp 	#$80 						; negative -> magnitude must be exactly $8000
		bne 	_AOGRange
		lda 	NSMantissa0,x
		bne 	_AOGRange
_AOGConvert:
		bit 	NSStatus,x 					; negative operands become two's complement, which is
		bpl 	_AOGDone 					; what GetInteger16Bit did. Mantissa2/3 are known zero
		jmp 	Negate16Bit 				; by now, so Negate16Bit's 16 bit reach is enough.
											; (jmp, not bmi: it lives in support/integers.asm,
											; well out of branch range from here.)
_AOGDone:
		rts
_AOGRange:
		.error_range

		.send 	code
		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		array.asm
;		Purpose:	Convert an array index reference to a physical address
;		Created:	27th April 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;						<i1> ARRAY1 <address>						one subscript
;						<i1> <i2> <i3> <icount> ARRAY <address>		two or more
;
;		Two entry points onto the same index walk. The compiler knows how many subscripts were
;		written, so for the single-subscript reference -- which is very nearly all of them -- it
;		emits ARRAY1 and leaves the count word off the stack entirely. That saves a p-code
;		dispatch to push the count and the GetInteger8Bit here to read it back.
;
;		In both cases the array's base address is pushed LAST and so is on top; the subscripts
;		are below it, and the first of them is the slot the resulting address is written back to.
;
; ************************************************************************************************

ArrayConvert1: ;; [array1]
		.entercmd
		phy
		lda 	NSMantissa0,x 				; base address -> zTemp1, as below
		sta 	zTemp1
		lda 	NSMantissa1,x
		clc
		adc 	variableStartPage
		sta 	zTemp1+1
		lda 	#1 							; exactly one subscript, and no count word was pushed
		sta 	zTemp2
		dex 								; so the single subscript sits directly below the base
		phx 								; and is the slot that will be replaced
		bra 	ACIndexLoop

ArrayConvert: ;; [array]
		.entercmd
		phy
		;
		;		Convert to a real address in zTemp1
		;
		lda 	NSMantissa0,x
		sta 	zTemp1
		lda 	NSMantissa1,x
		clc
		adc 	variableStartPage
		sta 	zTemp1+1
		;
		;		Set up for following, firstly get the number of levels to zTemp2, and point the
		;		stack to the first level.
		;
		dex 								; count of indices to follow -> zTemp2
		jsr 	GetInteger8Bit
		sta 	zTemp2 						; subtract from stack.

		txa
		sec
		sbc 	zTemp2
		tax
		phx 								; stack points at the first index, which will be replaced.
		;
		;		The loop for following down the indices. A global label, not the _-prefixed local
		;		it was: 64tass scopes a _ label to the enclosing global one, and ArrayConvert1
		;		above needs to branch in here from its own scope.
		;
ACIndexLoop:
		;
		;		GetInteger16Bit opens with .floatinteger, which IS jsr FloatIntegerPart, so the
		;		explicit call that used to stand here ran it twice on every index of every array
		;		access in the program. The second call could only ever take the do-nothing path:
		;		the first leaves NSExponent zero, which is the test FloatIntegerPart exits on. So
		;		it bought nothing and cost jsr+pha+lda+beq+pla+rts = 26 cycles an index.
		;
		jsr 	GetInteger16Bit 			; truncate to integer and fetch the index => zTemp0
		ldy 	#1 							; compare against the index count.
		lda 	zTemp0
		cmp 	(zTemp1)
		lda 	zTemp0+1
		sbc 	(zTemp1),y
		bcs 	_ACBadIndex 				; index error.
		dec 	zTemp2 						; decrement count, if zero, then innermost level
		beq 	_ACInnerLevel
		;
		;		Follow down a level
		;
		ldy 	#2 							; check sub index.
		lda 	(zTemp1),y
		bpl 	_ACBadIndex

		asl 	zTemp0 						; double the index and add it to the base address
		rol 	zTemp0+1 					
		clc
		lda		zTemp0
		adc 	zTemp1
		sta 	zTemp0	
		lda		zTemp0+1
		adc 	zTemp1+1
		sta 	zTemp0+1
		;
		;		Follow the link address and set up zTemp1 one level down.
		;
		ldy 	#3 							; we offset by 3 because 3 at entry, now get the address
		lda 	(zTemp0),y 					; into zTemp1 as a real address, not offset
		sta 	zTemp1
		iny
		lda 	(zTemp0),y
		clc
		adc 	variableStartPage
		sta 	zTemp1+1
		inx 								; next index
		bra 	ACIndexLoop
		;
		;		Reached the innermost level.
		;
_ACInnerLevel:
		;
		;		Check it is an inner level, and get the type
		;
		ldy 	#2
		lda 	(zTemp1),y
		bmi 	_ACBadIndex 				; it has sub arrays, so bad index.
		and 	#NSSTypeMask+NSSIInt16 		; check if it is an iFloat
		cmp 	#NSSIFloat
		bne 	_ACNotFloat
		;
		;		x2 or x6 depending on type.
		;
		lda 	zTemp0+1 					; double and add zTemp0 (x3)
		pha
		lda 	zTemp0

		asl 	zTemp0 						; x 2
		rol 	zTemp0+1

		clc 								; add back x 3
		adc 	zTemp0
		sta 	zTemp0
		pla
		adc 	zTemp0+1
		sta 	zTemp0+1
_ACNotFloat:
		asl 	zTemp0 						; x 2 or x 6 depending. 
		rol 	zTemp0+1
		;
		;		Add 3 , the prefix of the array structure
		;
		clc
		lda 	zTemp0
		adc 	#3
		sta 	zTemp0
		bcc 	_ACNoCarry
		inc 	zTemp0+1
_ACNoCarry:		
		;
		;		Add the base address of the array, making it back into an offset.
		;	
		plx 								; X points to first slot of array parameters
		clc
		lda 	zTemp0
		adc 	zTemp1
		sta 	NSMantissa0,x
		lda 	zTemp0+1
		adc 	zTemp1+1
		sec 	
		sbc 	variableStartPage
		sta 	NSMantissa1,x
		stz 	NSMantissa2,x
		stz 	NSMantissa3,x
		stz 	NSStatus,x
		stz 	NSExponent,x
		ply 	 							; restore code pointer

		.exitcmd

_ACBadIndex:
		plx 								; drop the saved parameter slot index, and
		ply 	 							; RESTORE THE CODE POINTER, exactly as the normal exit
											; above does. Every branch here (the two in the index
											; loop and the sub-array check) still has the entry
											; phy/phx on the stack, and Y is whatever the bounds
											; compare last left it -- 1. The error report prints
											; codePtr+Y, so without this the "@ $xxxx" was a fixed
											; meaningless address ($0002, or $FFFB when an implicit
											; array shifts things) no matter which line the bad
											; subscript was on, and GPC.ERR could only answer
											; "before the first mapped line". Same trap, and same
											; fix, as LoadSaveError in x16/commands/loadsave.asm.
		.error_index

		.send 	code
		
