; ************************************************************************************************
;
;					Clear workspace, reset string system, reset BASIC stack
;
; ************************************************************************************************

ClearMemory:		
		;
		;		Zero workspace
		;
		lda 	storeStartHigh 							; erase the work area
		sta 	zTemp0+1
		stz 	zTemp0
		phy
		ldy 	#0
_ClearLoop1:	
		lda 	#0
		sta 	(zTemp0),y
		iny
		bne 	_ClearLoop1	
		inc 	zTemp0+1
		lda 	zTemp0+1
		cmp 	storeEndHigh
		bne 	_ClearLoop1
		;
		;		Initialise string storage space.
		;
		;		This used to put the ceiling a QUARTER of the workspace below the top, under the
		;		comment "stack space = number of pages in total / 4". There is no stack up there.
		;		The runtime (FOR/GOSUB) stack is set up ten lines below this one, growing DOWN
		;		from storeStartHigh-1:$FF, and the compiler reserves FrameStackPages for it BELOW
		;		the workspace (see application/source/compiler/object.asm). So the top quarter
		;		was reserved for nothing -- and unreachable, because strings only ever grow down
		;		from this ceiling and arrays only ever grow up towards it. Measured on
		;		samples/FSIM16_V1: workspace $7900-$9F00, ceiling $9600, and the highest byte the
		;		program ever touched was $95FA. 2,304 of its 9,728 bytes, for nothing.
		;
		;		The ceiling is exclusive, so taking it right to the top is safe: StringConcrete
		;		subtracts the whole block size from it BEFORE writing a byte, and StringAllocTemp
		;		starts 512 below it, so the highest address either can touch is one less than
		;		this. storeEndHigh is already "the page after the last usable one" (00runtime.asm
		;		is handed $9F, and $9F00 is I/O), which is exactly what that needs.
		;
		lda 	storeEndHigh
		sta 	stringHighMemory+1
		stz 	stringHighMemory

		stz 	stringInitialised 						; string system not initialised
		;
		;		Initialise stack space.
		;
		jsr 	ResetRuntimeStack
		ply
		rts

; ************************************************************************************************
;
;					Put the FOR/GOSUB stack back at the top of its gap, empty
;
; ************************************************************************************************
;
;		Two callers, and the second one is the point of factoring this out.
;
;		ClearMemory does it because CLR is meant to throw the call stack away. But ClearMemory is
;		SKIPPED on a LOAD chain -- deliberately, so the loaded program inherits the variables --
;		and this went with it, so a chained program ran on the LOADER's stack pointer.
;
;		A chain cannot carry a call stack. The new program is entered through the ROM's RUN and
;		starts at its first line, so every frame the loader had is meaningless. Worse, the pointer
;		is derived from the LOADER's storeStartHigh: a small loader chaining to a bigger program
;		leaves it pointing inside the new program's OBJECT CODE, and each GOSUB wrote a frame over
;		it. That was silent until the frame-stack floor guard landed in build 114, which turned it
;		into an immediate OUT OF MEMORY on the first GOSUB -- louder, but still wrong.
;
;		StartRuntime therefore calls this on BOTH paths, before the chain test.
;
; ************************************************************************************************

ResetRuntimeStack:
		lda 	storeStartHigh 							; the stack sits just below the workspace
		dec 	a 										; and grows DOWN through the frame-stack gap
		sta 	runtimeStackPtr+1
		lda 	#$FF
		sta 	runtimeStackPtr
		sta 	(runtimeStackPtr) 						; A is still $FF -- the duff marker that stops
		rts 									 		; StackFindFrame walking off an empty stack

		.send 	code
		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		02/08/26		Stack reset factored out as ResetRuntimeStack, so StartRuntime can do it on
;						the LOAD-chain path too -- a chained program was running on the loader's
;						stack pointer.
;		02/08/26		String ceiling moved to the top of the workspace; it was a quarter down,
;						reserving space for a stack that lives below the workspace instead.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		compare.asm
;		Purpose:	Compare strings
;		Created:	12th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;						  Compare String S[X],S[X+1] - return 255,0,1
;
; ************************************************************************************************

CompareStrings: ;; [s.cmp]
		.entercmd

		dex
		
		lda 	NSMantissa0,x 				; copy strings to zTemp0 and zTemp1
		sta 	zTemp0
		lda 	NSMantissa1,x
		sta 	zTemp0+1

		lda 	NSMantissa0+1,x 			
		sta 	zTemp1
		lda 	NSMantissa1+1,x
		sta 	zTemp1+1

		phx
		phy

		lda 	(zTemp0)					; work out number to compare
		cmp 	(zTemp1)
		bcc 	_CSNIsSmallest 				; as min(len(s1),len(s2))
		lda 	(zTemp1)
_CSNIsSmallest:
		tax 								; count in X
		beq 	_CSNMatches 				; if zero already matches as far as we can go.
		ldy 	#0 							; start from offset 1
_CSNCompareString:
		iny 								; pre increment
		lda 	(zTemp0),y
		cmp 	(zTemp1),y
		bne 	_CSNDifferent 				; numbers are different.
		dex
		bne 	_CSNCompareString 			; compare common characters in two strings.
_CSNMatches:
		sec			
		lda 	(zTemp0)					; compare lengths
		sbc 	(zTemp1)
		beq 	_CSNSExit 					; if zero, then strings match and exit.
_CSNDifferent:
		lda 	#$FF
		bcc 	_CSNSExit
		lda 	#$01
_CSNSExit:
		ply
		plx
		cmp 	#0 							; set the flags.
		jsr 	FloatSetByte 				; output the byte
		.exitcmd

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		concrete.asm
;		Purpose:	Concrete string memory
;		Created:	11th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;									Concrete String YA -> YA
;
; ************************************************************************************************

StringConcrete:	
		stz 	stringInitialised	 		; initialise next usage

		sty 	zTemp2+1 					; save pointer to new string
		sta 	zTemp2
		;
		lda 	(zTemp2) 					; length required
		lsr 	a 							; allow half as much for expansion.
		clc
		adc 	(zTemp2)
		bcc 	_SCNoOverflow
		lda 	#255
_SCNoOverflow:
		cmp 	#10 						; and a minimum of 10
		bcs 	_SCNoMinimum		
		lda 	#10
_SCNoMinimum:
		sta 	zTemp1 						; save max length.
		;
		sec
		lda		stringHighMemory 			; subtract max length from high memory.
		sbc 	zTemp1
		tay
		lda 	stringHighMemory+1 	
		sbc 	#0
		pha
		;
		sec 								; subtract 3 more
		tya 							
		sbc 	#3
		sta 	stringHighMemory 			; to string high memory/zsTemp
		sta 	zsTemp
		;
		pla
		sbc 	#0
		sta 	stringHighMemory+1
		sta 	zsTemp+1
		;
		;		zsTemp is the base of the new block. Nothing checked it had anywhere to go.
		;
		;		This pointer only ever travels DOWN, and on the ASSIGNMENT path -- which is every
		;		A$=... in the language -- StringInitialise's out-of-memory test is never reached,
		;		because that only runs when something allocates a TEMPORARY (STR$, CHR$, concat).
		;		So the heap walked out of the bottom of the workspace, through the arrays, the
		;		scalars and the FOR/GOSUB stack, and into the p-code, and the program then executed
		;		its own string data. Measured 2026-08-02: a loop assigning a 36-character literal
		;		into a string array BRKed into the machine-language monitor on the 405th pass, with
		;		no error of any kind. It did the same on the pristine engine, 101 passes earlier.
		;
		;		availableMemory is the top of the array area (allocate.asm, dim.asm) -- the other
		;		end of the same free gap, and the mirror image of the test DIMWriteByte already
		;		makes when the arrays grow up towards us. Landing exactly on it is legal; the next
		;		temporary is what then reports the gap is gone, via StringInitialise's 512-byte
		;		margin.
		;
		;		Only A is used, so X (the numeric stack) and the returned YA are untouched, and the
		;		cost is a compare on each assignment that allocates.
		;
		cmp 	availableMemory+1
		bcc 	_SCNoMemory
		bne 	_SCRoom
		lda 	zsTemp
		cmp 	availableMemory
		bcc 	_SCNoMemory
_SCRoom:
		;
		lda 	zTemp1 						; set max length.
		sta 	(zsTemp)
		ldy 	#1 							; clear control byte.
		lda 	#0
		sta 	(zsTemp),y
		;
		lda 	zsTemp 						; new empty string in YA.
		ldy 	zsTemp+1
		rts

_SCNoMemory:
		.error_memory

		.send code

; ************************************************************************************************
;
;		Concreted string (total size = MaxLength + 3)
;
;		[Max length] [Control] [Act Length] [Data]
;		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		02/08/26		String heap now bounds-checked against availableMemory; the assignment path
;						had no out-of-memory test at all.
;
