		.section 	code

; ************************************************************************************************
;
;									.data <len> ASCIIZ code.
;
; ************************************************************************************************

CommandXData: ;; [.data]
		.entercmd
		tya 								; data length +1 added to Y
		sec 								
		adc 	(codePtr),y 				; next instruction
		tay
		.exitcmd

		.send 	code
		
