; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;								<RefAddr|Type> <Terminal> <Step> FOR
;
; ************************************************************************************************

CommandXFor: ;; [for]
		.entercmd
		;
		;		Stock BASIC REUSES the frame of an open FOR with the same index variable rather
		;		than opening a second one. Opening unconditionally leaked 19 bytes of frame stack
		;		every time a loop was abandoned and re-entered, so
		;
		;			20 FOR I=1 TO 5 : C=C+1 : IF C<500 THEN 20
		;
		;		runs forever interpreted but died compiled with OUT OF MEMORY after ~215 passes.
		;		Search first, as FNDFOR does. Only worth looking if the top frame is a FOR at all,
		;		because the search stops at the first frame that is not one.
		;
		lda 	(runtimeStackPtr)
		cmp 	#FRAME_FOR
		bne 	_CFNoReuse
		jsr 	ReuseForFrame
_CFNoReuse:
		lda 	#FRAME_FOR 					; open frame
		jsr 	StackOpenFrame
		jsr 	StackSaveCurrentPosition 	; normalise to Y=0 and save position.

		ldy 	#7 							; copy step out
		jsr 	CopyTOSToOffsetY
		dex
		ldy 	#13 						; copy terminal value.
		jsr 	CopyTOSToOffsetY
		dex

		;
		;		Bit 15 of the reference used to mean "int16 index", recorded here at frame
		;		offset 4 bit 7. NEXT never read that bit -- it wrote a raw float back into the
		;		two-byte slot, so a negative index came back as its magnitude. The compiler now
		;		rejects an int16 index outright, as stock X16 BASIC does (?SYNTAX ERROR), so
		;		this bit is always clear. Kept, with the masking below, so a stale object file
		;		that still sets it stores a flag nothing acts on rather than a bogus address.
		;
		lda 	NSMantissa1,x 				; bit 15 of reference indicates type int16
		and 	#$80
		ldy 	#4
		sta 	(runtimeStackPtr),y

		lda 	NSMantissa0,x 				; copy the reference address
		ldy 	#5 							; adjusted to be a real address
		sta 	(runtimeStackPtr),y
		sta 	zTemp0 						; also to zTemp0
		iny
		lda 	NSMantissa1,x
		clc
		and 	#$7F 						; throw the type bit.
		sta 	(runtimeStackPtr),y
		adc 	variableStartPage 			; point to variable page.
		sta 	zTemp0+1
		dex 								; throw reference.
		;
		;		We look for optimisation options. Here we have optimisation
		; 		if the index value, step value, and terminal value are all
		; 		positive integers, step is 1 byte - we can do it much more quickly.
		;
		ldy 	#5 							; check the index, step and terminal values
		lda 	(zTemp0),y 					; are all +ve integers, sign bits first.
		ldy 	#12 
		ora 	(runtimeStackPtr),y
		ldy 	#18
		ora 	(runtimeStackPtr),y
		and 	#$80 						; only interested in sign bit.
		;
		dey 								; now the exponents.
		ora 	(zTemp0),y
		ldy 	#11
		ora 	(runtimeStackPtr),y
		ldy 	#17
		ora 	(runtimeStackPtr),y

		ldy 	#8 							; step must be 1 byte.
		ora 	(runtimeStackPtr),y
		iny
		ora 	(runtimeStackPtr),y
		iny
		ora 	(runtimeStackPtr),y

		bne 	_CFNoOptimise
		;
		;		A ZERO step must never take the optimised path. Two reasons: its increment loop
		;		in next.asm propagates carry with "beq _CNOIncrement", and adding 0 to a 0 byte
		;		leaves 0 -- so with a zero index it walks Y straight off the end of the 4-byte
		;		variable, corrupting whatever follows. And the optimised exit test is a plain
		;		"terminal < value" magnitude check, which cannot express the exact-equality exit
		;		that STEP 0 requires. Send it to the general path, which handles both.
		;
		ldy 	#7 							; step low byte (mantissa1..3 are already known zero)
		lda 	(runtimeStackPtr),y
		beq 	_CFNoOptimise

		ldy 	#4 							; set the runtime stack pointer optimisation flag.
		lda 	(runtimeStackPtr),y
		ora 	#$40
		sta 	(runtimeStackPtr),y

_CFNoOptimise:
		ldy 	#0
		.exitcmd	

; ************************************************************************************************
;
;								Copy TOS to stack frame offset Y
;
; ************************************************************************************************

CopyTOSToOffsetY:
		lda 	NSMantissa0,x
		sta 	(runtimeStackPtr),y
		iny
		lda 	NSMantissa1,x
		sta 	(runtimeStackPtr),y
		iny
		lda 	NSMantissa2,x
		sta 	(runtimeStackPtr),y
		iny
		lda 	NSMantissa3,x
		sta 	(runtimeStackPtr),y
		iny
		lda 	NSExponent,x
		sta 	(runtimeStackPtr),y
		iny
		lda 	NSStatus,x
		sta 	(runtimeStackPtr),y
		rts

; ************************************************************************************************
;
;		Throw any open FOR frame using the same index variable as the FOR about to be opened,
;		along with every frame stacked above it, so the new frame reuses its space.
;
;		Walks a COPY of the stack pointer and only commits on a match, so a search that finds
;		nothing leaves the stack untouched. Stops at the first frame that is not a FOR, exactly
;		as the 6502 ROM does -- which is what makes an intervening GOSUB shield a subroutine's
;		FOR I from the caller's. The $FF stack-empty marker is not FRAME_FOR, so it stops there
;		too and needs no test of its own.
;
;		Y holds the code pointer offset on entry to a command, and StackOpenFrame's OUT OF
;		MEMORY reports codePtr+Y, so Y is saved and restored -- see blitz-error-codeptr-y.
;
; ************************************************************************************************

ReuseForFrame:
		phy
		dex 								; <reference> <terminal> <step>, so the index
		dex 								; variable reference is two below TOS.
		lda 	NSMantissa0,x
		sta 	zTemp2
		lda 	NSMantissa1,x
		and 	#$7F 						; frame offset 6 holds it with the type bit thrown.
		sta 	zTemp2+1
		inx
		inx
		;
		lda 	runtimeStackPtr 			; walk a copy
		sta 	zTemp1
		lda 	runtimeStackPtr+1
		sta 	zTemp1+1
_RFFLoop:
		lda 	(zTemp1) 					; still a FOR frame ?
		cmp 	#FRAME_FOR
		bne 	_RFFExit
		ldy 	#5 							; same index variable ?
		lda 	(zTemp1),y
		cmp 	zTemp2
		bne 	_RFFNext
		iny
		lda 	(zTemp1),y
		cmp 	zTemp2+1
		beq 	_RFFFound
_RFFNext:
		clc 								; step over the frame and try the next.
		lda 	zTemp1
		adc 	#FRAME_FOR & $1F
		sta 	zTemp1
		bcc 	_RFFLoop
		inc 	zTemp1+1
		bra 	_RFFLoop

_RFFFound:
		clc 								; discard it and everything above it.
		lda 	zTemp1
		adc 	#FRAME_FOR & $1F
		sta 	runtimeStackPtr
		lda 	zTemp1+1
		adc 	#0
		sta 	runtimeStackPtr+1
_RFFExit:
		ply
		rts

; ************************************************************************************************
;
;		0	FOR Marker 				[1]
;		1 	Page/Position for loop 	[3]
;		4 	Control 				[1] 	Integer/Int16:7 ; optimised:6
;		5 	Index Variable 			[2]  	Offset Address 
;		7 	Step (+1 optimise) 		[6]
;		13	Terminal Value.	 		[6]
;
; ************************************************************************************************

		.send 	code
		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		16/08/26		FOR now reuses the frame of an open FOR with the same index variable, as
;						stock BASIC's FNDFOR does. Opening unconditionally leaked 19 bytes of
;						frame stack per abandoned loop, so a program that ran forever interpreted
;						died compiled with OUT OF MEMORY after ~215 passes.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		frames.asm
;		Purpose:	Stack frame routines
;		Created:	19th April 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;										Open a frame
;
; ************************************************************************************************

StackOpenFrame:
		pha 								; save frame marker
		and 	#$1F 						; bytes required.
		sta 	zTemp0
		;
		sec 								; subtract from runtime stack pointer.
		lda		runtimeStackPtr
		sbc 	zTemp0
		sta 	runtimeStackPtr
		lda		runtimeStackPtr+1
		sbc 	#0
		sta 	runtimeStackPtr+1
		;
		;		...and refuse if that was one frame too many. Nothing tested this before: the
		;		stack simply carried on down out of the gap the compiler left for it and into the
		;		object code, so the program overwrote itself and then ran what it had written.
		;
		;		stackFloorHigh (00runtime.asm) is storeStartHigh - FrameStackPages, so it is page
		;		aligned; a frame is at most 31 bytes, so testing the high byte AFTER the subtraction
		;		is exact -- the new frame either starts inside the gap or it does not, and it cannot
		;		straddle. A is already the new high byte, so this costs six cycles a GOSUB.
		;
		;		OUT OF MEMORY, because that is what stock BASIC reports for too many nested GOSUBs.
		;
		cmp 	stackFloorHigh
		bcc 	_SOFOverflow
		;
		pla 								; put frame marker at +0
		sta 	(runtimeStackPtr)
		rts

_SOFOverflow:
		.error_memory

; ************************************************************************************************
;
;										Close a frame
;
; ************************************************************************************************

StackCloseFrame:
		lda 	(runtimeStackPtr)			; get frame marker
		and 	#$1F 						; size
		clc
		adc 	runtimeStackPtr
		sta 	runtimeStackPtr
		bcc 	_SCFNoCarry
		inc 	runtimeStackPtr+1
_SCFNoCarry:
		rts

; ************************************************************************************************
;
;									Find frame of type A
;
; ************************************************************************************************

StackFindFrame:
		sta 	requiredFrame
_SFFLoop:
		lda 	(runtimeStackPtr) 			; get TOS
		cmp 	#$FF 						; if found $FF then this is a fail.
		beq 	SCFFail 			
		cmp 	requiredFrame 				; found this type ?
		beq 	_SFFFound
		jsr 	StackCloseFrame 			; close the top frame
		bra 	_SFFLoop 					; and try te next.
_SFFFound:
		rts		

; ************************************************************************************************
;
;										Check a frame
;
; ************************************************************************************************

StackCheckFrame:
		cmp 	(runtimeStackPtr) 			; matches current frame
		bne 	SCFFail
		rts
SCFFail:
		.error_structure

		.send code

		.section storage
requiredFrame:
		.fill 	1
		.send 	storage		
		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		02/08/26		StackOpenFrame now refuses to grow the frame stack below stackFloorHigh; it
;						used to run on into the object code.
;		22/06/23 		Added StackFindFrame which looks for a frame of this type and throws
;						non matchers.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		fre.asm
;		Purpose:	Calculate free space
;		Created:	11th April 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;											FRE() function
;
; ************************************************************************************************

;
;		Free memory is the gap in the middle of the workspace: arrays grow UP from
;		availableMemory (support/allocate.asm, moved by dim.asm) and the string heap grows DOWN
;		from stringHighMemory (strings/concrete.asm). Whatever is between them is what a program
;		can still spend, and it is what the two out-of-memory tests measure against each other.
;
;		This used to subtract stringLowMemory, which was declared in data.inc, read here, and
;		WRITTEN NOWHERE -- so it was always zero and FRE returned the ADDRESS of the string
;		ceiling rather than a count. On a compiled samples/FSIM16_V1 that is 40704 where the
;		answer is about 5900. stringLowMemory has been deleted rather than maintained: it would
;		only have been a second copy of availableMemory, and two things that must agree is how
;		this codebase keeps hurting itself.
;
;		Measured against the ROM, 2026-08-02 (x16emu r49): stock X16 FRE returns a POSITIVE byte
;		count with no C64-style wrap above 32767 -- a 7-line program reported 38537 -- and the
;		argument is ignored, FRE(1) = FRE(0). A positive count is therefore right; the number
;		itself cannot match stock, because GPC has no BASIC program text in the way and lays its
;		scalars out at a fixed offset instead of allocating them from the same pool.
;
;		The two ends cannot cross, so this cannot underflow: DIMWriteByte refuses to let the
;		arrays reach the string ceiling's page, and StringConcrete refuses to bring the ceiling
;		below availableMemory. Equal is legal and returns 0.
;
UnaryFre:	;; [fre]
		.entercmd

		jsr 	FloatSetZero 				; zero the result (32 bit integer)
		sec
		lda 	stringHighMemory 			; free = string floor - top of the arrays
		sbc 	availableMemory
		sta		NSMantissa0,x
		lda 	stringHighMemory+1
		sbc 	availableMemory+1
		sta		NSMantissa1,x

		.exitcmd

		.send 	code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;		02/08/26		Subtract availableMemory, not the never-written stringLowMemory. FRE was
;						returning the string ceiling's address instead of a byte count.
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		get.asm
;		Purpose:	Get 1 character from input stream
;		Created:	21st April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

; ************************************************************************************************
;
;								GET char to stack as string
;
; ************************************************************************************************

		.section code

CommandXGet: ;; [get]
		.entercmd
		inx
		lda 	#1 							; 1 character space
		jsr 	StringAllocTemp 	

		jsr 	VectorGetCharacter 			; get a character
		cmp 	#0
		beq 	_CGNone

		phy
		ldy 	#1 							; store char
		sta 	(zsTemp),y
		tya 								; store length.
		sta 	(zsTemp)
		ply
_CGNone:		
		.exitcmd

		.send code

