;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;										PSET Command
;
; ************************************************************************************************

Command_PSET: ;; [pset]
		.entercmd
		phy
		jsr 	GetInteger8Bit 				; get the colour
		pha
		ldx 	#0 							; copy 0/1 to r0,r1
		ldy 	#X16_r0
		jsr 	GraphicsCopy2
		jsr 	X16_FB_cursor_position 		; set position.
		pla 								; set pixel.
		jsr 	X16_FB_set_pixel
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;										LINE Command
;
; ************************************************************************************************

Command_LINE: ;; [line]
		.entercmd
		phy
		jsr 	GraphicsColourOptional 		; LINE's colour is optional (keeps current if omitted)
		ldx 	#0 							; copy 0/1/2/3 to r0,1,2,3
		ldy 	#X16_r0
		jsr 	GraphicsCopy4
		jsr 	X16_GRAPH_draw_line
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;										RECT Command
;
; ************************************************************************************************

Command_RECT: ;; [rect]
		.entercmd
		phy
		jsr 	GraphicsRectCoords
		sec
		jsr 	X16_GRAPH_draw_rect
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;										FRAME Command
;
; ************************************************************************************************

Command_FRAME: ;; [frame]
		.entercmd
		phy
		jsr 	GraphicsRectCoords
		clc
		jsr 	X16_GRAPH_draw_rect
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;										OVAL Command
;
;		OVAL and RING are RECT and FRAME with the ellipse renderer in place of the rectangle
;		one. GRAPH_draw_oval takes its bounding box in r0..r3 and the fill flag in carry,
;		exactly as GRAPH_draw_rect does, so GraphicsRectCoords sets up both unchanged.
;
; ************************************************************************************************

Command_OVAL: ;; [oval]
		.entercmd
		phy
		jsr 	GraphicsRectCoords
		sec 								; carry set = filled
		jsr 	X16_GRAPH_draw_oval
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;										RING Command
;
; ************************************************************************************************

Command_RING: ;; [ring]
		.entercmd
		phy
		jsr 	GraphicsRectCoords
		clc 								; carry clear = outline
		jsr 	X16_GRAPH_draw_oval
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;										CHAR Command
;
; ************************************************************************************************

Command_CHAR: ;; [char]
		.entercmd
		phy
		dex  								; set the draw colour
		jsr 	GraphicsColour
		ldx 	#0 							; copy 0/1 to r0,r1
		ldy 	#X16_r0
		jsr 	GraphicsCopy2
		;
		lda 	NSMantissa0+3 				; copy string address to zTemp0
		sta 	zTemp0
		lda 	NSMantissa1+3
		sta 	zTemp0+1
		lda 	(zTemp0) 					; count of chars to zTemp1
		sta 	zTemp1
_CCLoop:
		lda 	zTemp1 						; done all chars ?
		beq 	_CCExit
		dec 	zTemp1 						; dec counter		
		inc 	zTemp0 						; pre-bump pointer
		bne 	_CCNoCarry
		inc 	zTemp0+1
_CCNoCarry:
		lda 	(zTemp0) 					; get character 
		jsr 	X16_GRAPH_put_char 			; write it
		bra 	_CCLoop						; go round.
_CCExit:		
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;								Set colour to stack X
;
; ************************************************************************************************

GraphicsColourOptional:
		.floatinteger 						; integer form of the colour argument.
		lda 	NSMantissa1,x 				; high byte is non-zero only for the 256 "omitted"
		bne 	_GCOKeep 					; marker OptionalColourCompile pushes -- so leave the
		lda 	NSMantissa0,x 				; current draw colour. Otherwise it is a real 0..255
		tax 								; colour (an explicit ",255" still lands here), set it.
		ldy 	#0
		jsr 	X16_GRAPH_set_colors
_GCOKeep:
		rts

GraphicsColour:
		jsr 	GetInteger8Bit
		tax
		ldy 	#0
		jsr 	X16_GRAPH_set_colors
		rts

; ************************************************************************************************
;
;								Copy stack X,X+n to rY,Y+n
;
; ************************************************************************************************

GraphicsCopy4:
		jsr 	GraphicsCopy2
GraphicsCopy2:
		jsr 	GraphicsCopy1
GraphicsCopy1:		
		.floatinteger
		lda 	NSMantissa0,x
		sta 	0,y
		lda 	NSMantissa1,x
		sta 	1,y
		inx
		iny
		iny
		rts

; ************************************************************************************************
;
;								Set up Rectangle and colour
;
; ************************************************************************************************

GraphicsRectCoords:
		jsr 	GraphicsColourOptional 		; set colour (optional: keeps current if omitted)
		ldx 	#0 							; copy in order.
		ldy 	#X16_r0
		jsr 	GraphicsCopy4 
		ldx 	#X16_r0 					; sort r0/r2
		jsr 	_GRCSortSubtract
		ldx 	#X16_r1 					; sort r1/r3
		jsr 	_GRCSortSubtract
		stz 	X16_r4-X16_r1,x 			; zero the corner rounding in r4. X is X16_r1 here, so
		stz 	X16_r4-X16_r1+1,x 			; the offset is 6, not 8 -- 8 lands on r5, which is not
		rts 								; an input to GRAPH_draw_rect and left r4 uninitialised.

_GRCSortSubtract:
		lda 	4,x 						; calculate r2-r0
		cmp 	0,x
		lda 	5,x
		sbc 	1,x
		bcs 	_GRCNoSwap 					; >= swap.
		jsr 	_GRCSwapByte 				; swap 0/2
		inx
		jsr 	_GRCSwapByte 				; swap 1/3
		dex
_GRCNoSwap:		
		sec 								; calculate width/height into 4,5
		lda 	4,x
		sbc 	0,x
		sta 	4,x

		lda 	5,x
		sbc 	1,x
		sta 	5,x

		inc 	4,x 						; size does not include limits.
		bne 	_GRCNoCarry
		inc 	5,x
_GRCNoCarry:		
		rts

_GRCSwapByte:
		lda 	4,x
		pha
		lda 	0,x
		sta 	4,x
		pla
		sta 	0,x
		rts		
		.send 	code
		
