; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		linput.asm
;		Purpose:	LINPUT, LINPUT# and BINPUT#
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		Two P-codes serve all three keywords, because the CHANNEL is not their business: the "#"
;		forms are compiled with the C: (channel execute) prefix, which sets currentChannel around
;		the command and puts it back afterwards. That is exactly how INPUT and INPUT# already
;		share one runtime. So:
;
;			[linput]	S[X] = a delimiter	->	S[X] = everything up to it
;			[binput]	S[X] = a count		->	S[X] = that many bytes
;
;		LINPUT (no #) is simply [linput] on channel 0 with a delimiter of 13, and channel 0 is the
;		KERNAL's screen editor -- CHRIN hands back the logical line a character at a time as the
;		user types it, with every editor key working. That is what LINPUT is FOR, and it is also
;		why the manual warns that an empty line comes back as a single space and trailing spaces
;		are lost: that is the editor's doing, not ours, and we inherit it for free.
;
;		END OF FILE is checked BEFORE each read, never after. The KERNAL sets ST when it hands
;		over the LAST byte, so that byte is real and must be kept; it is the NEXT read that has
;		nothing to give. Testing first keeps the last byte and still stops. See st.asm -- without
;		ST a program could not tell EOF from a blank line, and a read loop could never end.
;
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;					LINPUT <var$>  /  LINPUT# <n>,<var$>[,<delimiter>]
;
; ************************************************************************************************

CommandXLinput: ;; [!linput]
		.entercmd 							; S[X] is the delimiter
		phy
		jsr 	GetInteger8Bit
		sta 	liDelimiter
		phx 								; the KERNAL calls below are free to trash X, so park
											; the float stack pointer and use X as the index
		jsr 	LinputOpenChannel
		stz 	ReadBufferSize
_CLILoop:
		jsr 	LinputAtEndOfFile
		bne 	_CLIDone
		jsr 	X16_CHRIN
		cmp 	liDelimiter
		beq 	_CLIDone 					; the delimiter is consumed, but never stored
		ldx 	ReadBufferSize
		cpx 	#255 						; ReadBuffer is 255 bytes. A full one takes no more, but
		beq 	_CLILoop 					; still runs on to the delimiter, so that the next read
											; starts at the beginning of a line rather than mid-way
		sta 	ReadBuffer,x
		inc 	ReadBufferSize
		bra 	_CLILoop
_CLIDone:
		jsr 	LinputCloseChannel
		jsr 	LinputEchoNewLine 			; the keyboard's line ends by moving down a line
		plx
		jsr 	LinputResult
		ply
		.exitcmd

; ************************************************************************************************
;
;							BINPUT# <n>,<var$>,<len>
;
; ************************************************************************************************

CommandXBinput: ;; [!binput]
		.entercmd 							; S[X] is how many bytes are wanted
		phy
		jsr 	GetInteger8Bit
		sta 	liCount
		phx
		jsr 	LinputOpenChannel
		stz 	ReadBufferSize
_CBILoop:
		lda 	ReadBufferSize 				; got them all ?
		cmp 	liCount
		beq 	_CBIDone
		jsr 	LinputAtEndOfFile 			; "if there are fewer than <len> bytes available to
		bne 	_CBIDone 					; be read, fewer bytes will be stored"
		jsr 	X16_CHRIN
		ldx 	ReadBufferSize
		sta 	ReadBuffer,x
		inc 	ReadBufferSize
		bra 	_CBILoop
_CBIDone:
		jsr 	LinputCloseChannel
		plx
		jsr 	LinputResult
		ply
		.exitcmd

; ************************************************************************************************
;
;		Z clear when the channel has run out. Bit 6 of the KERNAL status is end of file.
;
;		Channel 0 is the screen editor and it NEVER runs out -- the user can always type another
;		line. READST is no help there either: the KERNAL does not update it for keyboard input, so
;		it still holds whatever the last SERIAL operation left, and a LOAD leaves bit 6 SET. Every
;		compiled program has just been LOADed, so ST is 64 before the program's first statement --
;		and testing it made the very first LINPUT report end of file and hand back an empty string
;		WITHOUT WAITING. The MD5 program printed "ENTER FILENAME:" and then hashed nothing at all.
;
;		So only ask the KERNAL about real files, and take channel 0 as never at end of file.
;
; ************************************************************************************************

LinputAtEndOfFile:
		lda 	currentChannel
		beq 	_LAEOFOpen 					; channel 0 : the keyboard, never at end of file
		jsr 	X16_READST
		and 	#$40
		rts
_LAEOFOpen:
		lda 	#0 							; Z set = still open, carry on reading
		rts

; ************************************************************************************************
;
;		Point the KERNAL's input at the current channel, and afterwards put it back. Channel 0
;		means the keyboard, which is CLRCHN's default, not a file to CHKIN.
;
; ************************************************************************************************

LinputOpenChannel:
		ldx 	currentChannel
		beq 	LinputCloseChannel
		jmp 	X16_CHKIN

LinputCloseChannel:
		jmp 	X16_CLRCHN

; ************************************************************************************************
;
;		A typed line ends by moving to the next one, and it is the KERNAL's own line input that
;		echoes that -- CHRIN alone does not, it only hands the characters back. So reading a line
;		with CHRIN leaves the cursor sitting where the typing stopped, and whatever the program
;		printed next ran on to the same line. Stock BASIC against ours, same program:
;
;			ENTER FILENAME: MD5                            stock: the hash goes on the next line
;			ENTER FILENAME: MD5 24E34541087ABC81D25...     ours: run together
;
;		Channel 0 only. A file read must not have a stray CR pushed at it, and there is no cursor
;		out there to move.
;
; ************************************************************************************************

LinputEchoNewLine:
		lda 	currentChannel
		bne 	_LENLExit 					; a real file: nothing to echo
		lda 	#13
		jmp 	X16_CHROUT
_LENLExit:
		rts

; ************************************************************************************************
;
;		Leave the buffer in S[X] as a string. ReadBufferSize is the length byte and ReadBuffer
;		follows it, which IS Blitz's string layout, so the buffer's own address is the string.
;		This overwrites the parameter that was in S[X], so the stack comes out level and the
;		store the compiler emits next pops the result straight into the variable.
;
; ************************************************************************************************

LinputResult:
		jsr 	FloatSetZero
		lda 	#ReadBufferSize & $FF
		sta 	NSMantissa0,x
		lda 	#ReadBufferSize >> 8
		sta 	NSMantissa1,x
		lda 	#NSSString
		sta 	NSStatus,x
		rts

		.send 	code

		.section storage
liDelimiter:
		.fill 	1
liCount:
		.fill 	1
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		load.asm
;		Purpose:	LOAD "<name>" -- chain-load and run another program
;		Created:	16th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		LOAD "<name>" loads another program over this one and runs it -- program chaining, the
;		same thing stock BASIC does when a LOAD is executed from a running program.
;
;		We do this the way it demonstrably works: by building a real one-line BASIC program
;
;			10 LOAD "<name>"
;
;		at the start of BASIC ($0801) and handing it to the ROM's RUN. LOAD, executed under a
;		genuine RUN (proper stack, CLR done, program-mode line number), loads the file over $0801
;		and chain-runs it exactly as the interpreter does -- which a synthetic single-statement
;		dispatch does NOT (the ROM's post-load rerun needs the full RUN context to land in the
;		interpreter loop; without it the load happens but nothing runs).
;
;		Layout built here (see the R49 ROM's newstt/RUN, disassembled to get this right):
;
;			$0800 : $00                the leading zero every BASIC program sits behind
;			$0801 : <link>             two bytes -> the $00 $00 end-of-program marker
;			$0803 : 10  0              line number, low/high
;			$0805 : $93 $22 <name> $22 $00     LOAD "<name>" , end of line
;			      : $00 $00            end of program
;
;		vartab is pointed just past that so RUN's CLR has an empty variable space, and txttab is
;		pinned to $0801.  RUN (.runc) sets TXTPTR = txttab-1, does CLR, resets the stack and RTSes
;		to the interpreter's per-statement loop at $CC60 (JMP newstt) -- so we push $CC5F for it
;		to return through.  Command_LOAD itself lives far above $0801, so writing the little
;		program here never touches the code doing the writing; and by the time RUN's LOAD
;		overwrites $0801 we are running in the ROM.
;
;		Variables carry across the chain, like stock's LOAD-in-a-program. RUN would normally CLR,
;		but the compiled runtime keeps its variables and strings in high RAM ($8100+), not BASIC's
;		variable space, and RUN's CLR does not touch that. What WOULD wipe them is the loaded
;		program's own StartRuntime, which clears memory -- so LOAD arms a signature (see below and
;		00runtime.asm) that tells StartRuntime this is a chain and to skip that clear. This only
;		makes sense when the two programs share a variable layout (the compiler assigns addresses
;		by first appearance, so declare the shared variables in the same order in both).
;
;		Zero page is clear: the runtime's ZP tops out around $79, well below txttab ($DF) and the
;		CHRGET/TXTPTR area ($E7/$EE), and it never touches $0200-$0800 or $03E1/$03EB.
;
; ************************************************************************************************

		.section 	code

LD_LOADTOK = $93 							; CBM BASIC token for LOAD
LD_PROG    = $0801 							; start of BASIC program space
LD_TXTTAB  = $00DF 							; ROM: start-of-program pointer
LD_VARTAB  = $03E1 							; ROM: start of variables (= end of program) -- CLR reads it
LD_RUN     = $CD30 							; ROM: the RUN statement
LD_RUNLOOP = $CC60 							; ROM: the "JMP newstt" a statement handler returns to

Command_LOAD: ;; [!load]
		.entercmd
		;
		;		zTemp0 -> filename string: a length byte followed by the characters.
		;
		lda 	NSMantissa0+0
		sta 	zTemp0
		lda 	NSMantissa1+0
		sta 	zTemp0+1
		;
		;		Arm the chain signature. The loaded program's StartRuntime sees it and skips its
		;		memory clear, so our variables (and strings) carry across the chain. It lives in
		;		low RAM, below $0801, so neither the load nor RUN's CLR disturbs it.
		;
		ldx 	#3
_LDArm:
		lda 	LoadChainMagic,x
		sta 	loadChainSig,x
		dex
		bpl 	_LDArm
		;
		;		Fixed part of the little program.
		;
		stz 	LD_PROG-1 					; $0800 = 0, the leading zero
		lda 	#10 						; line number 10
		sta 	LD_PROG+2
		stz 	LD_PROG+3
		lda 	#LD_LOADTOK 				; LOAD token
		sta 	LD_PROG+4
		lda 	#$22 						; opening quote
		sta 	LD_PROG+5
		;
		;		Copy the filename in, then close the quote, end the line, and mark end of program.
		;
		lda 	(zTemp0) 					; filename length
		sta 	ldNameLen
		ldy 	#0
_LDCopy:
		cpy 	ldNameLen
		beq 	_LDCopyDone
		iny
		lda 	(zTemp0),y 					; character i (1..len)
		sta 	LD_PROG+5,y 				; -> $0807 upward
		bra 	_LDCopy
_LDCopyDone:
		iny 								; closing quote
		lda 	#$22
		sta 	LD_PROG+5,y
		iny 								; end-of-line
		lda 	#0
		sta 	LD_PROG+5,y
		iny 								; end-of-program marker (two zero bytes)
		sta 	LD_PROG+5,y
		iny
		sta 	LD_PROG+5,y
		;
		;		Y = namelen+4.  The link at $0801 points to the first end-of-program byte, which is
		;		$0805 + Y; vartab is two past it (the byte after the second marker).
		;
		tya
		clc
		adc 	#$05 						; low of $0805 + Y
		sta 	LD_PROG 					; link low
		lda 	#$08
		adc 	#0
		sta 	LD_PROG+1 					; link high
		;
		lda 	LD_PROG 					; vartab = link + 2
		clc
		adc 	#2
		sta 	LD_VARTAB
		lda 	LD_PROG+1
		adc 	#0
		sta 	LD_VARTAB+1
		;
		lda 	#<LD_PROG 					; txttab = $0801
		sta 	LD_TXTTAB
		lda 	#>LD_PROG
		sta 	LD_TXTTAB+1
		;
		;		Enter RUN. Its CLR resets the stack and RTSes to $CC60 (JMP newstt); push $CC5F so
		;		it returns there and runs our one-line program -- which LOADs and chains.
		;
		lda 	#>(LD_RUNLOOP-1)
		pha
		lda 	#<(LD_RUNLOOP-1)
		pha
		lda 	#0 							; RUN's first act is to test Z: set => "RUN" (from the
		jmp 	LD_RUN 						; start), clear => "RUN <line>" (which would hunt for a
											; bogus line and raise UNDEF'D STATEMENT). Enter with Z=1.

		.send 	code

		.section storage
ldNameLen: 									; filename length, held across the copy loop
		.fill 	1
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		loadsave.asm
;		Purpose:	BLOAD, BVLOAD, VLOAD, BSAVE and BVERIFY
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		All five are the KERNAL's LOAD ($FFD5) and BSAVE ($FEBA) with SETNAM and SETLFS in front,
;		which is exactly what BASIC does with them. Two separate knobs decide what a load means,
;		and it is easy to conflate them:
;
;		The SECONDARY ADDRESS, given to SETLFS, says what to do with the file's first two bytes:
;
;			0	they are an address header; skip them and load at the address we passed
;			1	they are an address header; load THERE and ignore the address we passed
;			2	there is no header; load the whole file at the address we passed
;
;		The ACCUMULATOR, given to LOAD, says where the bytes go:
;
;			0	system memory			2	VRAM, from $00000 + address
;			1	verify, do not write	3	VRAM, from $10000 + address
;
;		So BLOAD is (secondary 2, A=0), BVLOAD is (secondary 2, A=2+bank), and VLOAD is the same
;		as BVLOAD but secondary 0 -- the one difference between them is that VLOAD eats the
;		two byte header and BVLOAD does not. BVERIFY is (secondary 2, A=1).
;
;		LOAD into banked RAM starts at whatever bank $00 selects and advances it by itself when a
;		file runs past $BFFF, so setting the bank IS the whole of the bank handling.
;
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;		Carry set means the KERNAL reported a failure. This is reached by jsr rather than by a
;		branch on purpose: the five commands are spread over far more than a branch can reach,
;		and carry survives a jsr untouched.
;
;		EVERY error path comes through the jsr, so that the stack below is always the same shape.
;
; ************************************************************************************************

LoadSaveCheckError:
		bcs 	LoadSaveError
		rts

LoadSaveError: 								; the stack here is [ saved Y ][ return address ], so
		pla 								; the return address has to be dropped before the saved Y
		pla 								; can be reached. Y is the interpreter's instruction
		ply 								; pointer, LOAD and BSAVE trash it, and the error report
		.error_channel 						; prints codePtr+Y -- so without this the "@ $xxxx" is
											; a line picked at random, which is exactly the false
											; trail that hid the OPEN bug for so long.

; ************************************************************************************************
;
;						BLOAD <filename>,<device>,<bank>,<address>
;
; ************************************************************************************************

Command_BLOAD: ;; [!bload]
		.entercmd
		phy
		ldx 	#3
		jsr 	LoadSaveIntegers

		lda 	NSMantissa0+2 				; the bank the load begins in
		sta 	SelectRAMBank
		sta 	ramBank

		lda 	#2 							; no header: BLOAD takes the file exactly as it is
		jsr 	LoadSaveSetup

		lda 	#0 							; into system memory
		ldx 	NSMantissa0+3
		ldy 	NSMantissa1+3
		jsr 	X16_LOAD
		jsr 	LoadSaveCheckError 			; carry set = the KERNAL failed

		stx 	SYS_Reg_X 					; "after a successful load, $030D and $030E will contain
		sty 	SYS_Reg_Y 					; the address of the final byte loaded + 1"
		lda 	SelectRAMBank 				; LOAD advances the bank as it fills each one, and BLOAD
		sta 	ramBank 					; leaves it where it stopped, as if BANK had been called
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;			BVLOAD <filename>,<device>,<VERA high>,<VERA low>   -- raw, no header
;			VLOAD  <filename>,<device>,<VERA high>,<VERA low>   -- skips a two byte header
;
; ************************************************************************************************

Command_BVLOAD: ;; [!bvload]
		.entercmd
		phy
		lda 	#2 							; no header
		bra 	VLoadCommon

Command_VLOAD: ;; [!vload]
		.entercmd
		phy
		lda 	#0 							; skip the two byte address header

VLoadCommon: 								; global, not a cheap local: BVLOAD branches in from
		pha 								; its own scope, and _locals do not cross one
		ldx 	#3
		jsr 	LoadSaveIntegers
		pla
		jsr 	LoadSaveSetup

		lda 	NSMantissa0+2 				; LOAD takes A=2 for VRAM at $00000 + address and A=3
		and 	#1 							; for $10000 + address, so the VERA high address is
		clc 								; simply added on
		adc 	#2
		ldx 	NSMantissa0+3
		ldy 	NSMantissa1+3
		jsr 	X16_LOAD
		jsr 	LoadSaveCheckError 			; carry set = the KERNAL failed
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;					BSAVE <filename>,<device>,<bank>,<start>,<end>
;
; ************************************************************************************************

Command_BSAVE: ;; [!bsave]
		.entercmd
		phy
		ldx 	#4
		jsr 	LoadSaveIntegers

		lda 	SelectRAMBank 				; the manual documents BLOAD and BVERIFY as leaving the
		sta 	lsSavedBank 		 		; bank where they stopped, "as if you called BANK", and
		lda 	NSMantissa0+2 				; says nothing at all about BSAVE. A save cannot advance
		sta 	SelectRAMBank 				; a bank, so there is nothing to report -- put it back
											; rather than silently redirect the next PEEK.
		lda 	#1 							; secondary 1 is the CBM "this is a save" convention
		jsr 	LoadSaveSetup 				; -- and it uses zTemp0, so the start address below
											; has to be put there AFTERWARDS, not before
		lda 	NSMantissa0+3 				; BSAVE wants the start address in zero page and A
		sta 	zTemp0 						; holding the address OF that pointer
		lda 	NSMantissa1+3
		sta 	zTemp0+1

		ldx 	NSMantissa0+4 				; and the EXCLUSIVE end in XY: "the save will stop one
		ldy 	NSMantissa1+4 				; byte before <end address>"
		lda 	#zTemp0
		jsr 	X16_BSAVE
		php 								; putting the bank back must not lose the carry that
		lda 	lsSavedBank 				; says whether the save worked
		sta 	SelectRAMBank
		plp
		jsr 	LoadSaveCheckError 			; carry set = the KERNAL failed
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;					BVERIFY <filename>,<device>,<bank>,<start>
;
;		FOUR parameters, not the five the manual gives it. "BVERIFY <filename>,<device>,<bank>,
;		<start address>,<end address>" is a hard ?SYNTAX ERROR in the R49 ROM -- run it and see.
;		BSAVE's signature looks to have been copied into the manual by mistake. Four is also what
;		the KERNAL implies: LOAD with A=1 verifies, and takes no end address, because the length
;		of the file is what bounds the comparison.
;
;		Stock reports a mismatch by setting ST, and Blitz has no ST -- it is a CBM pseudo variable
;		rather than a keyword, and nothing in the compiler recognises it. A compiled program that
;		could not see the answer would be pointless, so a mismatch is raised as an I/O error.
;		That is a deliberate difference from stock, and the only one here.
;
; ************************************************************************************************

Command_BVERIFY: ;; [!bverify]
		.entercmd
		phy
		ldx 	#3
		jsr 	LoadSaveIntegers

		lda 	NSMantissa0+2
		sta 	SelectRAMBank
		sta 	ramBank

		lda 	#2 							; no header
		jsr 	LoadSaveSetup

		lda 	#1 							; compare, do not write
		ldx 	NSMantissa0+3
		ldy 	NSMantissa1+3
		jsr 	X16_LOAD
		jsr 	LoadSaveCheckError 			; carry set = the KERNAL failed

		jsr 	X16_READST 					; bit 4 is the CBM "verify mismatch" flag
		and 	#$10
		beq 	_BVMatched
		sec 								; a mismatch is raised as an I/O error, and raised through
		jsr 	LoadSaveCheckError 			; the same jsr a KERNAL failure uses rather than jumping
											; straight to LoadSaveError -- that is the stack depth
											; LoadSaveError unwinds. It does not come back.
_BVMatched:
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;		Make S[1]..S[X] integers. S[0] is the filename and is skipped -- it is a string, and
;		FloatIntegerPart would happily maul its address into nonsense.
;
; ************************************************************************************************

LoadSaveIntegers:
_LSILoop:
		.floatinteger
		dex
		bne 	_LSILoop
		rts

; ************************************************************************************************
;
;		SETNAM from the filename in S[0] and SETLFS from the device in S[1], with the secondary
;		address in A. Clobbers X, so it must be called once the parameters are already integers.
;
; ************************************************************************************************

LoadSaveSetup:
		sta 	lsSecondary
		lda 	NSMantissa0+0 				; the string's first byte is its length and the
		sta 	zTemp0 						; characters follow it, so XY has to point one on
		tax
		lda 	NSMantissa1+0
		sta 	zTemp0+1
		tay
		inx
		bne 	_LSSNoCarry
		iny
_LSSNoCarry:
		lda 	(zTemp0)
		jsr 	X16_SETNAM

		lda 	#0 							; logical file number 0, which is what BASIC's own LOAD
		ldx 	NSMantissa0+1 				; and SAVE use. This is NOT free to pick: a load or a
		ldy 	lsSecondary 				; save leaves its number registered, so using 1 here
		jsr 	X16_SETLFS 					; made a later OPEN 1 fail or hang. 0 is reserved for
		rts 								; exactly this and belongs to nobody.

		.send 	code

		.section storage
lsSecondary:
		.fill 	1
lsSavedBank: 								; BSAVE puts the RAM bank back; see the note there
		.fill 	1
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		location.asm
;		Purpose:	Save/Restore location on stack.
;		Created:	19th April 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;					Normalise position so it Y = 0 and save at stack offset +1
;
; ************************************************************************************************

StackSaveCurrentPosition:
		jsr 	FixUpY 						; codePtr,Y is corrected so Y = 0
		phy
		ldy 	#2
		lda 	codePtr
		sta 	(runtimeStackPtr),y
		iny
		lda 	codePtr+1
		sta 	(runtimeStackPtr),y
		ply
		rts

; ************************************************************************************************
;
;										Close a frame
;
; ************************************************************************************************

StackLoadCurrentPosition:
		ldy 	#2
		lda 	(runtimeStackPtr),y
		sta 	codePtr
		iny
		lda 	(runtimeStackPtr),y
		sta 	codePtr+1
		ldy 	#0
		rts

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		machine.asm
;		Purpose:	POWEROFF, RESET and REBOOT
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The three keywords that stop or restart the machine. They are not interchangeable, and it
;		is worth being exact about which is which, because two of them were the wrong way round
;		here. Read out of BASIC ROM bank 4 -- the extended keyword vector table is at $C0A0 and is
;		C64 style, so each entry holds its handler's address minus one:
;
;			POWEROFF	$E7BC	one I2C write, SMC $42 offset 1. Cuts the power.
;			RESET		$E7B8	one I2C write, SMC $42 offset 2. The SMC asserts the reset LINE,
;								so this is a HARD reset -- the same as the physical reset switch.
;			REBOOT		$E6EF	jmp ($FFFC). A SOFT reset: no hardware is reset at all, the KERNAL
;								simply starts again through its own reset vector.
;
;		REBOOT used to do RESET's I2C write, which made a compiled REBOOT hard reset the machine.
;		The manual agrees with the ROM on both, and it was this file that was wrong.
;
; ************************************************************************************************

		.section 	code

X16_SMC_Device = $42 						; the SMC's I2C address
X16_SMC_PowerOff = 1 						; offset 1 : cut the power
X16_SMC_Reset = 2 							; offset 2 : assert the reset line

; ************************************************************************************************
;
;									POWEROFF and RESET
;
;		One I2C write to the System Management Controller each, which is what BASIC does for them.
;		Neither takes a parameter, so X arrives as $FF (an empty stack) and only has to be put
;		back that way after we borrow it for the device number.
;
; ************************************************************************************************

X16CommandPowerOff: ;; [!poweroff]
		.entercmd
		phy
		ldy 	#X16_SMC_PowerOff
		bra 	X16SMCWrite

X16CommandReset: ;; [!reset]
		.entercmd
		phy
		ldy 	#X16_SMC_Reset

X16SMCWrite: 								; global, not a cheap local: POWEROFF branches here
		ldx 	#X16_SMC_Device 			; from its own scope, and _locals do not cross one.
		lda 	#0
		jsr 	X16_i2c_write_byte
		bcs 	X16SMCError
		ply 								; the write returns, and the SMC only acts a moment
		ldx 	#$FF 						; later, so we do carry on running until it does.
		.exitcmd 							; Tidy up properly rather than assume we die here.

X16SMCError:
		ply 								; put the interpreter's instruction pointer back before
		.error_channel 						; the error report, which prints codePtr+Y

; ************************************************************************************************
;
;										REBOOT
;
;		A software reset, straight through the ROM's own reset vector.
;
;		The bank switch is not tidying up, it is the whole trick. $C000-$FFFF is banked, and only
;		bank 0 holds a real reset vector: bank 4, which is the one we are running under, has $AA
;		filler at $FFFA-$FFFF, so jmp ($FFFC) without the stz would jump to $AAAA. (Bank 4 gets
;		away with that because its $FF00 page is a table of trampolines into bank 0, which is also
;		why every KERNAL call in this runtime works without ever touching $01.)
;
;		BASIC cannot do these two instructions inline -- it IS the ROM it is banking away, so it
;		copies a six byte stub to $0100 and jumps to that. We run from RAM, so there is nothing to
;		pull out from under us and the stub is unnecessary.
;
;		No sei, for the same reason BASIC does not bother with one: the KERNAL's reset entry masks
;		interrupts itself, and until it does the IRQ vector still points somewhere valid.
;
; ************************************************************************************************

X16CommandReboot: ;; [!reboot]
		.entercmd
		stz 	SelectROMBank 				; bank 0 = KERNAL, the only bank with a reset vector
		jmp 	($FFFC) 					; and we do not come back

		.send 	code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		mod.asm
;		Purpose:	MOD(dividend,divisor) function
;		Created:	13th July 2026
;		Reviewed: 	No
;		Author : 	Steven De George SR
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;								MOD(<dividend>,<divisor>)
;
;		The truncated remainder, so the result takes the sign of the DIVIDEND:
;		-7 MOD 3 is -1, and 7 MOD -3 is 1.
;
;		Int32Divide already does all the work, we just keep the half that DivideInt32 throws
;		away. It is an unsigned mantissa divide leaving the quotient in S[X+2] and the
;		remainder in S[X], and it clears S[X] with FloatSetZeroMantissaOnly -- the mantissa
;		and nothing else -- so the dividend's status byte survives the divide untouched. That
;		byte is its sign, which is exactly the sign a truncated remainder needs, so there is
;		no sign fixup here at all. (Contrast FloatCalculateSign, which DivideInt32 uses to xor
;		the two signs together: right for a quotient, wrong for a remainder.)
;
;		The X16 ROM restricts MOD to 16 bit signed operands. Blitz does not need to: this is
;		a full 32 bit remainder, which is a superset.
;
; ************************************************************************************************

UnaryMOD: ;; [mod]
		.entercmd 							; X is the divisor, the dividend is below it at S[X-1]
		phy
		jsr 	FloatIntegerPart 			; make the divisor an integer
		jsr 	FloatIsZero 				; dividing by zero is an error
		beq 	_UMDivideByZero
		dex 								; X is now the dividend, so S[X+1] is the divisor
		jsr 	FloatIntegerPart 			; make the dividend an integer
		jsr 	Int32Divide 				; S[X] mantissa = |dividend| mod |divisor|
		stz 	NSExponent,x 				; below the divisor, so it is a whole number
		jsr 	FloatIsZero 				; a zero remainder must not come back as -0
		bne 	_UMExit
		stz 	NSStatus,x
_UMExit:
		ply
		.exitcmd

_UMDivideByZero:
		.error_divzero

		.send 	code

