XCommandMouse: ;; [!mouse]
		.entercmd
		jsr 	GetInteger8Bit 				; mouse control.
		dex
		phx
		phy
		pha
		sec 								; get screen resolution
		jsr 	X16_screen_mode
		pla
		jsr 	X16_mouse_config 			; config the mouse
		ply
		plx
		.exitcmd

; ************************************************************************************************
;
;									Mouse status functions
;
; ************************************************************************************************

XUnaryMB: ;; [!mb]
		.entercmd
		jsr 	XUnaryMouseCommon
		lda 	zTemp2
		inx
		jsr 	FloatSetByte
		.exitcmd

XUnaryMX: ;; [!mx]
		.entercmd
		jsr 	XUnaryMouseCommon
		lda 	zTemp0
		inx
		jsr 	FloatSetByte
		lda 	zTemp0+1
		sta 	NSMantissa1,x
		.exitcmd

XUnaryMY: ;; [!my]
		.entercmd
		jsr 	XUnaryMouseCommon
		lda 	zTemp1
		inx
		jsr 	FloatSetByte
		lda 	zTemp1+1
		sta 	NSMantissa1,x
		.exitcmd

XUnaryMWheel: ;; [!mwheel]
		.entercmd
		jsr 	XUnaryMouseCommon 			; read mouse status
		inx
		lda 	zTemp2+1 					; set mantissa to |wheel|
		pha
		bpl 	_XUMNotNegative
		eor 	#$FF
		inc 	a
_XUMNotNegative:		
		jsr 	FloatSetByte
		pla  								; negate if it was -ve
		bpl 	_XUMNotNegative2
		jsr 	FloatNegate
_XUMNotNegative2:
		.exitcmd

XUnaryMouseCommon:
		phx
		phy
		ldx 	#zTemp0
		jsr 	X16_mouse_get
		sta 	zTemp2
		stx 	zTemp2+1
		ply
		plx
		rts

		.send 	code
		
