ReadFloatCommand:
		.entercmd
		.vaddress
		jsr 	ReadFloatZTemp0Sub
		.exitcmd

ReadFloatZTemp0Sub:
		phy 								; start write
		ldy 	#1
		inx

		lda 	(zTemp0)
		sta 	NSMantissa0,x
		
		lda 	(zTemp0),y
		sta 	NSMantissa1,x
		iny

		lda 	(zTemp0),y
		sta 	NSMantissa2,x
		iny

		lda 	(zTemp0),y
		sta 	NSMantissa3,x
		iny

		lda 	(zTemp0),y
		sta 	NSExponent,x
		iny

		lda 	(zTemp0),y
		sta 	NSStatus,x

		ply
		rts

		.send 	code
		
