; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		rnd.asm
;		Purpose:	Random number function
;		Created:	11th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;											RND function
;
; ************************************************************************************************

UnaryRND:	;; [rnd]
		.entercmd

		bit 	NSStatus,x 					; -ve then set seed from operand
		bpl 	_URNoSeed

		jsr 	FloatNormalise 				; some float value
		lda 	NSMantissa0,x 				; copy to Mantissa
		sta 	randomSeed+0
		lda 	NSMantissa1,x
		sta 	randomSeed+1
		lda 	NSMantissa2,x
		sta 	randomSeed+2
		lda 	NSMantissa3,x
		sta 	randomSeed+3
_URNoSeed:
		jsr 	RandomNumberGenerator 		; create a number and copy to mantissa

		lda 	randomSeed+0
		sta 	NSMantissa0,x		
		lda 	randomSeed+1
		sta 	NSMantissa1,x		
		lda 	randomSeed+2
		sta 	NSMantissa2,x		
		lda 	randomSeed+3
		and 	#$7F
		sta 	NSMantissa3,x		
		lda 	#(-31 & $FF)
		sta 	NSExponent,x
		stz 	NSStatus,x
		
		.exitcmd

; ************************************************************************************************
;
;						Random number generator, originally by Brad Smith
;
; ************************************************************************************************

RandomNumberGenerator:
		phy
		lda 	randomSeed+0 				; check if zero
		ora 	randomSeed+1
		ora 	randomSeed+2
		ora 	randomSeed+3
		bne 	_RNGNoSeed

		dec 	randomSeed+3 				; if so tweak and flog
		ldy 	#100
		bra 	_RNGLoop

_RNGNoSeed:									; do 8 times.
		ldy 	#8
		lda 	randomSeed+0
_RNGLoop:
		asl		a
		rol 	randomSeed+1
		rol 	randomSeed+2
		rol 	randomSeed+3
		bcc		_RNGSkip
		eor 	#$C5
_RNGSkip:	
		dey
		bne		_RNGLoop
		sta 	randomSeed+0
		ply
		rts

		.send code

		.section storage
randomSeed:
		.fill 	4
		.send 	storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		rpt.asm
;		Purpose:	RPT$()
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		RPT$(<byte>,<count>) is CHR$ with a repeat count, and it is built the same way: allocate
;		a temp string of the right length, write the length byte, then fill it.
;
;		StringAllocTemp puts the new string's address into S[X], so the dex below is what makes
;		the result land in the FIRST argument's slot, which is where a function's result belongs.
;
; ************************************************************************************************

		.section 	code

UnaryRPT: ;; [!rpt$]
		.entercmd
		;
		;		The count is the last argument. It cannot go through GetInteger8Bit, which just
		;		takes the low byte of the mantissa -- RPT$(65,300) would quietly hand back 44
		;		characters instead of complaining. Stock raises ?ILLEGAL QUANTITY for a count of
		;		zero as well, rather than returning an empty string, so zero is an error too.
		;
		.floatinteger
		lda 	NSStatus,x 					; negative
		bmi 	_URPTRange
		lda 	NSMantissa1,x 				; or too big to be a byte
		ora 	NSMantissa2,x
		ora 	NSMantissa3,x
		bne 	_URPTRange
		lda 	NSMantissa0,x
		beq 	_URPTRange 					; or zero
		sta 	rptCount

		dex 								; X now addresses the character -- and that is also
		jsr 	GetInteger8Bit 				; the slot the result has to be left in
		sta 	rptChar

		lda 	rptCount
		jsr 	StringAllocTemp 			; address into zsTemp, and into S[X] as the result
		lda 	rptCount
		sta 	(zsTemp) 					; the length byte comes first

		phy 								; Y is the code position
		ldy 	rptCount
_URPTFill:
		lda 	rptChar
		sta 	(zsTemp),y
		dey
		bne 	_URPTFill
		ply
		.exitcmd

_URPTRange:
		.error_range

		.send 	code

		.section storage
rptCount:
		.fill 	1
rptChar:
		.fill 	1
		.send storage

