		.send 	code
		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		ti.asm
;		Purpose:	Read time in jiffies as integer (ti) or string (ti$)
;		Created:	20th April 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;									     Time to TOS
;
; ************************************************************************************************

TimeTOS:	;; [ti]
		.entercmd
		jsr 	TIPushClock 				; push clock to TOS
		.exitcmd

TimeString: ;; [ti$]
		.entercmd
		jsr 	TIPushClock 				; push clock to TOS
		jsr 	_TSDivMod60 				; result in seconds

		jsr 	_TSDivMod60 				; seconds
		pha
		jsr 	_TSDivMod60 				; minutes
		pha
		lda 	#24 						; hours
		jsr 	_TSDivModA
		pha

		lda 	#6
		jsr 	StringAllocTemp
		pla
		jsr 	_TSWriteDecimal
		pla
		jsr 	_TSWriteDecimal
		pla
		jsr 	_TSWriteDecimal

		.exitcmd

; ************************************************************************************************
;
;								Divide S[X] by A/60, return modulus in A
;
; ************************************************************************************************

_TSDivMod60:
		lda 	#60
_TSDivModA:
		inx
		jsr 	FloatSetByte
		dex
		jsr 	Int32Divide
		lda 	NSMantissa0,x 				; get modulus
		pha
		jsr 	NSMCopyPlusTwoToZero 		
		pla
		rts

; ************************************************************************************************
;
;									Convert A to BCD, Copy to string
;
; ************************************************************************************************

_TSWriteDecimal:
		phx
		ldx 	#'0'
_TSWDLoop:
		cmp 	#10
		bcc 	_TSWDEnd
		sbc 	#10
		inx
		bra 	_TSWDLoop
_TSWDEnd:
		pha
		txa
		jsr 	StringWriteChar
		pla
		ora 	#'0'
		jsr 	StringWriteChar				
		plx	
		rts
		
; ************************************************************************************************
;
;									Push clock (60Hz) to TOS
;	
; ************************************************************************************************

TIPushClock:
		phy
		inx 								; push 0 on the stack
		jsr 	FloatSetZero
		phx
		jsr 	XReadClock 					; read time into YXA
		stx 	zTemp0
		plx
		sta 	NSMantissa0,x
		lda 	zTemp0
		sta 	NSMantissa1,x
		tya
		sta 	NSMantissa2,x
		ply
		rts
		.send 	code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		tiledata.asm
;		Purpose:	TDATA() and TATTR()
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		The read half of TILE. Both share TileSetAddress (tiles.asm), which leaves VERA pointing
;		at the cell with the auto-increment on -- so the tile is the first byte read and its
;		attribute is the second.
;
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;								TDATA(<x>,<y>) and TATTR(<x>,<y>)
;
; ************************************************************************************************

UnaryTDATA: ;; [!tdata]
		.entercmd
		phy 								; Y is the code position
		lda 	#0 							; TDATA wants the tile itself
		bra 	TileRead

UnaryTATTR: ;; [!tattr]
		.entercmd
		phy
		lda 	#1 							; TATTR wants the attribute, one byte further on

TileRead: 									; global, not a cheap local: TDATA branches in from
		sta 	tileSelect 					; its own scope and _locals do not cross one
		.floatinteger 						; y is the last argument, so it is the one X is on
		lda 	NSMantissa0,x
		sta 	tileY
		lda 	NSMantissa1,x
		sta 	tileY+1
		dex 								; X now addresses x -- which is also the slot the
		.floatinteger 						; result has to be left in, first argument's slot
		lda 	NSMantissa0,x
		sta 	tileX
		lda 	NSMantissa1,x
		sta 	tileX+1
		jsr 	TileSetAddress

		lda 	tileSelect
		beq 	_TRRead
		lda 	VRAMData0 					; step over the tile to reach its attribute
_TRRead:
		lda 	VRAMData0
		jsr 	FloatSetByte
		ply
		.exitcmd

		.send 	code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		tiles.asm
;		Purpose:	TILE, and the layer 1 map address it shares with TDATA and TATTR
;		Created:	14th July 2026
;		Reviewed: 	No
;
; ************************************************************************************************
; ************************************************************************************************
;
;		TILE, TDATA and TATTR are conveniences over layer 1's tile map: they work out the VRAM
;		address of a character cell so a program does not have to. Each map entry is two bytes,
;		the tile (or screen code) and its attribute (the foreground/background colours in text
;		mode), so the address of cell (x,y) is
;
;			mapbase + y * rowbytes + x * 2
;
;		Both mapbase and rowbytes are read from VERA every time rather than assumed, because the
;		manual is explicit that these work "if VERA Layer 1's map base value is changed or the
;		map size is changed". In the default 80x60 text mode that is a 128-tile-wide map at
;		$1B000, so a row is 256 bytes and the cell is $1B000 + y*256 + x*2 -- but nothing here
;		depends on that.
;
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;						TILE <x>,<y>,<tile/screen code>[,<attribute>]
;
; ************************************************************************************************

Command_TILE: ;; [!tile]
		.entercmd
		phy
		ldx 	#3
_CTLInteger:
		.floatinteger
		dex
		bpl 	_CTLInteger

		lda 	NSMantissa0+0
		sta 	tileX
		lda 	NSMantissa1+0
		sta 	tileX+1
		lda 	NSMantissa0+1
		sta 	tileY
		lda 	NSMantissa1+1
		sta 	tileY+1
		jsr 	TileSetAddress

		lda 	NSMantissa0+2 				; the tile or screen code, and the auto-increment
		sta 	VRAMData0 					; then steps on to the attribute

		lda 	NSMantissa0+3 				; the attribute is optional. 255 means it was not
		cmp 	#255 						; supplied, and the cell keeps the colours it had.
		beq 	_CTLNoAttribute
		sta 	VRAMData0
_CTLNoAttribute:
		ply
		ldx 	#$FF
		.exitcmd

; ************************************************************************************************
;
;		Point VERA data port 0 at the layer 1 map entry for the cell in tileX,tileY, with the
;		auto-increment set so that a second access reaches the attribute byte. X is untouched.
;
; ************************************************************************************************

TileSetAddress:
		lda 	VERAL1Config 				; a map row is 2 x (32 << map width) bytes, which is
		lsr 	a 							; 64 << map width. So the row offset is y shifted
		lsr 	a 							; left by 6 + map width, and the width field is
		lsr 	a 							; bits 5:4 of L1_CONFIG.
		lsr 	a
		and 	#3
		clc
		adc 	#6
		tay 								; Y = shift count, 6 to 9

		lda 	tileY 						; a 24 bit accumulator, because a 256 x 256 map of
		sta 	tileAddr 					; two byte entries is 128K -- the whole of VRAM
		lda 	tileY+1
		sta 	tileAddr+1
		stz 	tileAddr+2
_TSARow:
		asl 	tileAddr
		rol 	tileAddr+1
		rol 	tileAddr+2
		dey
		bne 	_TSARow

		lda 	tileX 						; + x * 2, one for the tile and one for its attribute
		asl 	a
		sta 	tileTemp
		lda 	tileX+1
		rol 	a
		sta 	tileTemp+1

		clc
		lda 	tileAddr
		adc 	tileTemp
		sta 	tileAddr
		lda 	tileAddr+1
		adc 	tileTemp+1
		sta 	tileAddr+1
		lda 	tileAddr+2
		adc 	#0
		sta 	tileAddr+2

		lda 	VERAL1MapBase 				; the map base register holds address bits 16:9, so
		stz 	tileTemp 					; the base is that shifted left by nine. Nine zero low
		asl 	a 							; bits means it only ever reaches the middle byte and
		sta 	tileTemp+1 					; bit 16.
		lda 	#0
		rol 	a
		sta 	tileTemp+2

		clc
		lda 	tileAddr
		adc 	tileTemp
		sta 	VRAMLow0
		lda 	tileAddr+1
		adc 	tileTemp+1
		sta 	VRAMMed0
		lda 	tileAddr+2
		adc 	tileTemp+2
		and 	#VRAMBank1 					; VRAM is 17 bits, so bit 16 is all that is left
		ora 	#VRAMIncrement1
		sta 	VRAMHigh0
		rts

		.send 	code

		.section storage
tileX:
		.fill 	2
tileY:
		.fill 	2
tileAddr: 									; 24 bit, see above
		.fill 	3
tileTemp:
		.fill 	3
tileSelect: 								; TDATA reads the tile, TATTR the byte after it
		.fill 	1
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		tiwrite.asm
;		Purpose:	Set TI from string
;		Created:	4th May 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;										TI = functionality
;
; ************************************************************************************************

CommandTIWriteN: ;; [!ti.write]
		.entercmd
		bra 	WriteTOSToClock

; ************************************************************************************************
;
;										TI$ = functionality
;
; ************************************************************************************************

CommandTIWriteS: ;; [!ti$.write]
		.entercmd
		lda 	NSMantissa0,x 				; copy string address to ZSTemp
		sta 	zsTemp
		lda 	NSMantissa1,x
		sta 	zsTemp+1
		lda 	(zsTemp) 					; check if it is six
		cmp 	#6
		bne 	CTIWError
		jsr 	FloatSetZero
		jsr 	CTIWDigitPair 				; do a digit pair 3 times
		jsr 	CTIWDigitPair
		jsr 	CTIWDigitPair
		lda 	#60 						; multiply the result by 60.
		jsr 	CTIWMultiply

WriteTOSToClock:
		phx
		phy

		lda 	NSMantissa1,x 				; get time into YXA
		pha
		lda 	NSMantissa2,x
		tay
		lda 	NSMantissa0,x
		plx

		jsr 	XWriteClock 				; update the clock.

		ply
		plx
		dex 								; throw result.
		.exitcmd
;
;		Add a pair of digits x 60
;
CTIWDigitPair:
		lda 	#6 							; x 6 
		jsr 	CTIWMultiply
		jsr 	CTIWAddDigit 				; add digit
		lda 	#10 						; x 10
		jsr 	CTIWMultiply
		jsr 	CTIWAddDigit 				; add digit
		rts
;
;		Add the next digit, validating.
;		
CTIWAddDigit:
		inc 	zsTemp 						; pre-increment
		bne 	CTIWASkip
		inc 	zsTemp+1
CTIWASkip:
		lda 	(zsTemp) 					; read and validate it
		sec
		sbc 	#"0"
		bcc 	CTIWError
		cmp 	#9+1
		bcs 	CTIWError
		inx 								; store at +1
		jsr 	FloatSetByte
		dex
		jsr 	FloatAddTopTwoStack
		rts

;
;		Multiply by A
;
CTIWMultiply: 								
		inx
		jsr 	FloatSetByte
		dex
		jsr 	FloatMultiplyShort
		rts

CTIWError:
		.error_value

		.send 	code
		
