		.section 	code

; ************************************************************************************************
;
;								Write integer (2 byte command)
;
; ************************************************************************************************

WriteIntegerCommand:
		.entercmd
		.vaddress
		jsr 	WriteIntegerZTemp0Sub
		.exitcmd

WriteIntegerZTemp0Sub:
		.floatinteger
		phy 								; start write
		ldy 	#1
		lda 	NSStatus,x 					; negate 2's comp if -ve
		bmi 	_WIZNegative

		lda 	NSMantissa0,x 				; +ve write
		sta 	(zTemp0)
		lda 	NSMantissa1,x
		sta 	(zTemp0),y
		ply
		dex
		rts

_WIZNegative:
		sec 								; -ve read
		lda 	#0
		sbc 	NSMantissa0,x
		sta 	(zTemp0)
		lda 	#0
		sbc 	NSMantissa1,x
		sta 	(zTemp0),y
		ply
		dex
		rts
		.send 	code
		
