; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		x16_i2c.asm
;		Purpose:	I2C Peek/Poke
;		Created:	9th May 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;								I2CPOKE device,register,value
;
; ************************************************************************************************

X16I2CPoke: ;; [!I2CPOKE]
		.entercmd
		phy
		jsr 	GetInteger8Bit 				; value
		pha
		dex
		jsr 	GetInteger8Bit 				; register
		pha
		dex
		jsr 	GetInteger8Bit 				; device
		tax 			
		ply
		pla
		jsr 	X16_i2c_write_byte 			; write the byte out.
		bcs 	X16I2CError
		ply
		ldx 	#$FF
		.exitcmd

X16I2CError: 								; both callers arrive with the saved Y on top of the stack
		ply 								; -- the interpreter's instruction pointer, trashed by the
		.error_channel 						; I2C call. The error report prints codePtr+Y.

; ************************************************************************************************
;
;									I2CPEEK(device,register)
;
; ************************************************************************************************

X16I2CPeek: ;; [!I2CPEEK]		
		.entercmd
		phx
		phy
		jsr 	GetInteger8Bit 				; register
		pha
		dex
		jsr 	GetInteger8Bit 				; device
		tax 								; X device
		ply 								; Y register
		jsr 	X16_i2c_read_byte 			; read I2C
		bcs 	X16I2CError
		ply 								; restore Y/X
		plx
		dex 								; drop TOS (register)
		jsr 	FloatSetByte 				; write read value to TOS.
		.exitcmd

		.send code

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		x16_open.asm
;		Purpose:	OPEN
;		Created:	2nd May 2023
;		Reviewed: 	No
;		Author : 	Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section 	code

; ************************************************************************************************
;
;					<logical> <device> <secondary> <filename> OPEN command
;
; ************************************************************************************************

CommandXOpen: ;; [open]
		.entercmd
		phy 								; Y is the INTERPRETER'S INSTRUCTION POINTER -- the
											; offset from codePtr that NextCommand fetches through.
											; SETLFS loads Y with the secondary address, so without
											; this, every OPEN resumed execution at codePtr plus
											; whatever the KERNAL left in Y, and whether the program
											; survived was pure luck of code layout: the same OPEN
											; worked at one line offset and crashed at another.
		;
		;		Set up the file name
		;
		lda 	NSMantissa0+3  				; point zTemp0 to string head, also in XY
		sta 	zTemp0
		tax
		lda 	NSMantissa1+3
		sta 	zTemp0+1
		tay

		inx 								; XY points to first character
		bne 	_CONoCarry
		iny
_CONoCarry:
		lda 	(zTemp0) 					; get length of filename
		jsr 	X16_SETNAM
		;
		; 		Set up the logical channel.
		;
		lda 	NSMantissa0+0
		ldx 	NSMantissa0+1
		ldy 	NSMantissa0+2
		jsr 	X16_SETLFS
		;
		;		Open
		;
		jsr 	X16_OPEN
		bcs 	_COError
		ply
		ldx 	#$FF 						; empty the float stack, as every other command does.
											; This is NOT cosmetic: OPEN reads its arguments from
											; slots 0-3 ABSOLUTELY, which only works if the stack
											; started empty. Leaving X at 3 meant a SECOND OPEN in
											; a program read garbage and handed the KERNAL a junk
											; filename pointer.
		.exitcmd
_COError:
		ply 								; the error report prints codePtr+Y, so put Y back
		.error_channel 						; first or the @ address is nonsense

		.send 	code
		
; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		x16_peekpoke.asm
;		Purpose:	Read/Write memory
;		Created:	20th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code

; ************************************************************************************************
;
;											Write Memory
;
; ************************************************************************************************

XPokeMemory:
		stx 	zTemp0
		sty 	zTemp0+1

		ldy 	SelectRAMBank 				; old RAM bank in Y
		ldx 	ramBank 					; switch to BANKed RAMBank if not $FF
		cpx 	#$FF
		beq 	_XPMNoSwitch
		stx 	SelectRAMBank
_XPMNoSwitch:
		sta 	(zTemp0) 					; do the POKE
		sty 	SelectRAMBank 				; reselect previous RAM Bank.		
_XPMExit:
		rts

; ************************************************************************************************
;
;											Read Memory
;
; ************************************************************************************************

XPeekMemory:
		stx 	zTemp0
		sty 	zTemp0+1

		ldy 	SelectRAMBank 				; old RAM bank in Y
		ldx 	ramBank 					; switch to BANKed RAMBank if not $FF
		cpx 	#$FF
		beq 	_XPMNoSwitch
		stx 	SelectRAMBank
_XPMNoSwitch:
		lda 	(zTemp0) 					; do the PEEK
		sty 	SelectRAMBank 				; reselect previous RAM bank.
		rts


; ************************************************************************************************
;
;											BANK command
;
; ************************************************************************************************

CommandBank: ;; [!bank]
		.entercmd
		lda 	NSMantissa0 				; RAM bank
		sta 	ramBank 					; store & make current
		sta 	SelectRAMBank
		lda 	NSMantissa0+1 		 		; ROM specified 
		cmp 	#$FF
		beq 	_CBNoUpdate
		sta 	romBank 					; this doesn't set the hardware page.
_CBNoUpdate:		
		ldx 	#$FF
		.exitcmd

		.send code

		.section storage
ramBank:
		.fill 	1
romBank:
		.fill 	1
		.send storage

; ************************************************************************************************
;
;									Changes and Updates
;
; ************************************************************************************************
;
;		Date			Notes
;		==== 			=====
;
; ************************************************************************************************
; ************************************************************************************************
; ************************************************************************************************
;
;		Name:		printchar.asm
;		Purpose:	Character output interface
;		Created:	11th April 2023
;		Reviewed: 	No
;		Author:		Paul Robson (paul@robsons.org.uk)
;
; ************************************************************************************************
; ************************************************************************************************

		.section code
		
; ************************************************************************************************
;
;						Print character A to Channel X: 13 should be CR, 32 space
;
;										Channel 0 is the screen.
;
; ************************************************************************************************

XPrintCharacterToChannel:
		pha
		phx
		phy

		pha  								; save char
		cpx 	#0 							; check default (0)
		bne 	_XPCNotDefault
		jsr 	X16_CLRCHN					; set default channel
		bra 	_XPCSend
_XPCNotDefault:		
		jsr 	X16_CHKOUT 					; CHKOUT set channel
		jsr 	X16_READST 					; check okay
		bne 	_XPCError
_XPCSend:		
		pla 								; restore character
		jsr 	X16_BSOUT 					; print

		ply
		plx
		pla
		rts
_XPCError:
		pla 								; drop the saved character, uncovering the saved Y --
		ply 								; the interpreter's instruction pointer, which CHKOUT has
		.error_channel 						; just trashed. The error report prints codePtr+Y.

		.send code

